/**
 * Writes supabase/seed.sql from validated content. Run with `pnpm content:seed`.
 *
 * Stage 1: only the fictional test fixtures. Approved real scripts will be
 * added here once a reviewer signs them off.
 */
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { buildSeedSql, SeedError } from '../src/db/seed';
import { TEST_QUESTIONS, TEST_SCRIPTS } from '../src/fixtures';

const target = fileURLToPath(new URL('../../../supabase/seed.sql', import.meta.url));

const header = [
  'GENERATED by `pnpm content:seed` (packages/shared/scripts/build-seed.ts). Do not edit.',
  '',
  'Local development seed. Runs after migrations on `supabase db reset`.',
  'Contains FICTIONAL test fixtures only. These diseases do not exist.',
].join('\n');

try {
  writeFileSync(target, buildSeedSql(TEST_SCRIPTS, TEST_QUESTIONS, header));
  console.log(
    `Wrote ${TEST_SCRIPTS.length} scripts and ${TEST_QUESTIONS.length} questions to ${target}`,
  );
} catch (error) {
  if (error instanceof SeedError) {
    console.error(error.message);
    process.exit(1);
  }
  throw error;
}
